53	// rawEqual 对合法配置保持兼容比较，但尾随内容使比较失败（而非按首个值判等）。
54	func TestRawEqualStrictness(t *testing.T) {
55		if rawEqual(json.RawMessage(`{"a":1}`), json.RawMessage(`{"a":1} null`)) {
56			t.Fatal("trailing null must not compare equal")
57		}
58		if rawEqual(json.RawMessage(`{"a":1}`), json.RawMessage(`{"a":1} x`)) {
59			t.Fatal("trailing text must not compare equal")
60		}
61		if !rawEqual(json.RawMessage(`{"a":1,"b":2}`), json.RawMessage("\t{ \"b\": 2.0, \"a\": 1.0 }\n")) {
62			t.Fatal("field order, whitespace and numeric equivalents must compare equal")
63		}
64		if rawEqual(json.RawMessage(`{"list":[1,2]}`), json.RawMessage(`{"list":[2,1]}`)) {
65			t.Fatal("array order must matter")
66		}
67		if rawEqual(json.RawMessage(`{"a":1}`), json.RawMessage(`{"a":1,"b":null}`)) {
68			t.Fatal("missing field must differ from null")
69		}
70	}
