204	// claimInstall 完成下载并领取安装，返回安装操作标识。
205	func claimInstall(t *testing.T, s *Store, spec CampaignSpec, id string, at time.Time) string {
206		t.Helper()
207		dl, err := s.Claim(spec.ID, id, at)
208		if err != nil || dl == nil || dl.Kind != StageDownload {
209			t.Fatalf("claim download: %v %+v", err, dl)
210		}
211		if err := s.SubmitResult(OperationResult{
212			CampaignID: spec.ID, DeviceID: id, OperationID: dl.ID,
213			At: at.Add(time.Minute), Success: true,
214		}); err != nil {
215			t.Fatalf("download result: %v", err)
216		}
217		in, err := s.Claim(spec.ID, id, at.Add(2*time.Minute))
218		if err != nil || in == nil || in.Kind != StageInstall {
219			t.Fatalf("claim install: %v %+v", err, in)
220		}
221		return in.ID
222	}
