	DesiredExists bool
	// ReportedExists 表示上报配置在该路径是否存在值。
	ReportedExists bool
	// Desired 是期望配置在该路径的原始 JSON，不存在时为 nil。
	Desired json.RawMessage
	// Reported 是上报配置在该路径的原始 JSON，不存在时为 nil。
